examples.template:
MonarchSectionCard(
    title = {{dangerZone.heading}},
    description = {{dangerZone.description}},
    tone = MonarchTone.Danger,
) {
    Column(
        modifier = Modifier.semantics { isTraversalGroup = true },
        verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1),
    ) {
        MonarchText(text = {{dangerZone.title}}, style = MonarchTextStyle.BodyStrong, heading = true)
        MonarchText(text = {{dangerZone.itemDescription}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchButton(
            text = {{dangerZone.action}},
            onClick = {
                step = "review"
                typed = ""
                open = true
            },
            variant = MonarchButtonVariant.Danger,
        )
    }
}
if (open) {
    // While the work runs, a swipe, back or a tap outside does not close the sheet.
    MonarchBottomSheet(onDismissRequest = { open = false }, dismissible = !deleting) {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            val stepNumber = listOf("review", "confirm", "verify", "done").indexOf(step) + 1
            if (stepNumber in 1..4 && step != "verify") {
                MonarchText(text = "Step $stepNumber of 4", style = MonarchTextStyle.Caption)
                MonarchProgress(progress = stepNumber / 4f, size = MonarchProgressSize.Sm)
            }
            when (step) {
                "review" -> {
                    MonarchText(text = {{flow.title}}, style = MonarchTextStyle.Title)
                    MonarchText(text = {{flow.heading}}, style = MonarchTextStyle.Subheading)
                    MonarchText(text = {{flow.intro}})
                    MonarchConsequenceList(
                        items = listOf(
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{impactLabels.apps}}, count = {{impact.apps}}),
                            MonarchConsequence(MonarchConsequenceKind.Removed, {{impactLabels.records}}, count = {{impact.records}}),
                            MonarchConsequence(MonarchConsequenceKind.Changed, {{impactLabels.members}}, count = {{impact.members}}),
                            MonarchConsequence(MonarchConsequenceKind.Changed, {{impactLabels.subscriptions}}, count = {{impact.subscriptions}}),
                            MonarchConsequence(MonarchConsequenceKind.Changed, {{impactLabels.domains}}, count = {{impact.domains}}),
                        ),
                        grouped = true,
                    )
                    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                        MonarchButton(
                            text = {{flow.cancel}},
                            onClick = { open = false },
                            modifier = Modifier.weight(1f),
                        )
                        MonarchButton(
                            text = {{flow.continue}},
                            onClick = { step = "confirm" },
                            modifier = Modifier.weight(1f),
                            variant = MonarchButtonVariant.Primary,
                        )
                    }
                }
                "confirm" -> {
                    MonarchTypeToConfirmInput(
                        phrase = workspace,
                        value = typed,
                        onValueChange = { typed = it },
                        label = "Type $workspace to confirm",
                    )
                    MonarchButton(
                        text = {{dangerZone.action}},
                        onClick = { step = "verify" },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Danger,
                        enabled = MonarchTypeToConfirmInputDefaults.matches(typed, workspace),
                    )
                    MonarchButton(
                        text = {{flow.cancel}},
                        onClick = { open = false },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Ghost,
                    )
                }
                "verify" -> {
                    failure?.let { MonarchInlineNotice(message = it, tone = MonarchTone.Danger) }
                    MonarchStepUpAuthDialog(
                        onVerify = { _ ->
                            // Send the credential to the server; throw if it is refused.
                        },
                        description = "Deleting a workspace needs you to confirm it’s you.",
                        onCancel = { step = "confirm" },
                        onVerified = {
                            deleting = true
                            failure = null
                            scope.launch {
                                // Delete on the server. On failure: failure = "Couldn’t delete the workspace."
                                deleting = false
                                step = "done"
                            }
                        },
                        onVerifyingChange = { deleting = it },
                    )
                }
                else -> {
                    MonarchText(text = "$workspace was deleted", style = MonarchTextStyle.Title)
                    MonarchText(text = "Members were signed out of it and its plan was cancelled.")
                    MonarchButton(
                        text = "Done",
                        onClick = { open = false },
                        modifier = Modifier.fillMaxWidth(),
                        variant = MonarchButtonVariant.Primary,
                    )
                }
            }
        }
    }
}

